python3 - <<'PY'
p='src/types/checker/functions/resolution/specialization.rs'
s=open(p).read()
old = """                // A BY-REFERENCE array parameter never adopts a call site's element type. The
                // narrowing below is safe for a by-VALUE parameter because the callee owns its
                // copy; a by-reference one writes into the CALLER's storage, and a body compiled
                // for `array<int>` that widens mid-call — a loop storage contract, an element
                // write of a `Mixed` value — rewrites that storage to boxed slots while the
                // caller still reads raw ones.
                // `function f(array &$a) { foreach ($a as $k => $v) { $a[$k] = $v * 2; } }` over
                // `[1, 2, 3]` printed three ADDRESSES for exactly that reason, and so did the
                // same body reached through a method or an untyped `&$a`. Keeping `array<mixed>`
                // makes the widening the CALL SITE's job, where
                // `ir_lower::expr::call_arg_coercion::lower_by_ref_array_arg_with_signature`
                // already converts the caller's local and re-types it.
                let by_ref_param = stored_sig
                    .ref_params
                    .get(seen_idx)
                    .copied()
                    .unwrap_or(false);
                // A by-reference parameter whose BODY widened its element type keeps that
                // widened type: it is what the caller's storage now holds. The narrowing
                // below would undo it on the next call and hand a body compiled for raw
                // slots an array of boxes.
                let by_ref_widened = by_ref_param"""
new = """                // A BY-REFERENCE parameter that `resolve_function_signature` already widened
                // keeps its widened element type. The narrowing below is safe for a by-VALUE
                // parameter because the callee owns its copy; a by-reference one writes into
                // the CALLER's storage, so re-narrowing it here would hand a body compiled for
                // raw slots an array of boxes on the very next call —
                // `function f(array &$a) { foreach ($a as $k => $v) { $a[$k] = $v * 2; } }`
                // over `[1, 2, 3]` printed three ADDRESSES for the mirror of this mistake.
                // A by-reference parameter the body does NOT widen still specializes normally,
                // which is what keeps a `sort($a)` callee on raw slots the backend can sort.
                let by_ref_param = stored_sig
                    .ref_params
                    .get(seen_idx)
                    .copied()
                    .unwrap_or(false);
                let by_ref_widened = by_ref_param"""
assert s.count(old)==1
open(p,'w').write(s.replace(old,new))
print('comment corrected')
